// logging system
import Log = require('jibo-log');
/**
 * Creates new Log instance.
 * @private
 * @param {String} name The name of the log (scoped).
 * @param {Boolean} enableErrorHandling Flag to enable uncaught error handling/exceptions (defaults to disabled).
 * @return {Object} The new log instance.
 */
export function createLog(name:string, enableErrorHandling?:boolean): Log {
    let log = new Log(name);
    if (enableErrorHandling) {
        // log.handleAll = true;  // FIXME this should be handled centrally
    }

    log.toSyslog(); // only works on linux/arm
    return log;
}


